 */
public final class DeltaT {
    private DeltaT() {
    }

    /**
     * Estimate Delta T for the given date. This is based on Espenak and Meeus, "Five Millennium Canon of
     * Solar Eclipses: -1999 to +3000" (NASA/TP-2006-214141).
